/* The two languages share the same lesson structure and mathematical models. */
function card(title,body,tone='blue',kicker=''){return `<section class="concept-card ${tone}">${kicker?`<div class="card-kicker">${kicker}</div>`:''}<h3>${title}</h3>${body}</section>`;}
function formula(body,caption=''){return `<div class="formula">${body}${caption?`<small>${caption}</small>`:''}</div>`;}
function section(title,sub=''){return `<div class="sectionline"><h2>${title}</h2>${sub?`<span class="small">${sub}</span>`:''}</div>`;}
function practice(body){return section(L('Coba pemahamanmu','Try the idea'),L('Pelan-pelan, satu soal dulu.','One question at a time.'))+`<div class="practice-grid">${body}</div>`;}
function reflection(id,label,placeholder){return `<div class="reflection-card"><div class="card-kicker">${L('CATATAN PEMIKIRANMU','YOUR THINKING NOTES')}</div><label for="reflection-${id}">${label}</label><textarea id="reflection-${id}" data-reflection="${id}" rows="3" placeholder="${placeholder}">${esc(memory.answers['reflection-'+id]||'')}</textarea><small>${L('Tersimpan otomatis di peramban ini.','Saves automatically in this browser.')}</small></div>`;}
function home(){return `<section class="hero"><div><div class="eyebrow">${L('JELAJAH MATEMATIKA BERSAMA MEILANI','A MATHEMATICAL EXPLORATION FOR MEILANI')}</div><h1>${L('Perubahan kecil.<br><em>Penemuan besar.</em>','Small changes.<br><em>Big discoveries.</em>')}</h1><p class="intro">${L('Hai, Meilani. Bagaimana cara menemukan jawaban terbaik tanpa mencoba semua kemungkinan?','Hi, Meilani. How can we find the best possible answer without trying every possibility?')}</p><p class="intro">${L('Mari kenali kalkulus lewat gambar, percobaan, dan pertanyaan sederhana.','Discover calculus through pictures, experiments, and small questions.')}</p><a class="primary" href="#garden">${L('Mulai menjelajah','Enter the atelier')} <span>→</span></a><div class="hero-tags"><span>↔ ${L('Coba dan amati','Play with ideas')}</span><span>✧ ${L('Petunjuk saat perlu','Hints when needed')}</span><span>✓ ${L('Tanpa batas waktu','No timer')}</span></div></div><div class="heroart">${heroArt()}<div class="art-caption">${L('MULAI DARI RASA INGIN TAHU.','LET CURIOSITY LEAD THE WAY.')}</div></div></section>${section(L('Alur penjelajahanmu','Your path of discovery'),L('Tiga sesi.<br>Ikuti ritmemu.','Three sessions.<br>At your own pace.'))}<div class="pathcards">${[['garden','01',L('Amati perubahannya.','Notice the change.'),L('Coba bentuk taman, amati gerak, lalu temukan makna turunan.','Experiment with a garden, observe motion, and discover what a derivative means.'),L('SESI 1 · AMATI & TEMUKAN','SESSION 1 · OBSERVE & DISCOVER')],['optimize','02',L('Temukan nilai terbaik.','Find the sweet spot.'),L('Hubungkan aljabar, geometri, dan kalkulus untuk mencari nilai maksimum.','Connect algebra, geometry, and calculus to find a maximum.'),L('SESI 2 · HUBUNGKAN & SELESAIKAN','SESSION 2 · CONNECT & SOLVE')],['box','03',L('Jelaskan alasanmu.','Think like a mathematician.'),L('Buat model kotak, uji pilihanmu, dan buktikan mengapa pilihan itu terbaik.','Model a box, test your choice, and explain why it is the best.'),L('SESI 3 · COBA & JELASKAN','SESSION 3 · EXPLORE & EXPLAIN')]].map(([link,n,t,p,k])=>`<a class="pathcard" href="#${link}"><div class="number">${n}</div><span class="arrow">↗</span><h3>${t}</h3><p>${p}</p><span class="small">${k}</span></a>`).join('')}</div><div class="quote"><b>✧</b><span>${L('Belum pernah belajar kalkulus? Tidak apa-apa. Kita mulai dari hal yang sudah kamu kenal.','New to calculus? That is fine. We will start with ideas you already know.')}</span></div>${!storageWorks?`<div class="note">${L('Penyimpanan peramban tidak tersedia. Unduh catatanmu sebelum menutup halaman.','Browser storage is unavailable. Download your notes before closing the page.')}</div>`:''}`;}
function garden(){return heading(L('01 · TEKA-TEKI PEMBUKA','01 · THE OPENING PUZZLE'),L('Satu pagar. Banyak bentuk taman.','One fence. Many possibilities.'),L('Kamu punya pagar sepanjang 24 meter untuk mengelilingi keempat sisi taman persegi panjang. Ukuran mana yang membuat tamannya paling luas? Coba dulu, tanpa rumus baru.','You have 24 metres of fencing for all four sides of a rectangular garden. Which dimensions give the largest area? Experiment first—no new formulas needed.'))+`<div class="lab"><div class="stage"><div class="stage-label">${L('PERCOBAAN TAMAN · KELILING TETAP 24 m','GARDEN EXPERIMENT · PERIMETER FIXED AT 24 m')}</div><div id="garden-art"></div><div class="art-caption">${L('Pagarnya sama panjang. Luas tamannya bisa berbeda.','The same fence can enclose different amounts of space.')}</div></div><div class="panel"><div class="card-kicker">${L('COBA SENDIRI','TRY IT YOURSELF')}</div><h2>${L('Ubah satu sisinya.','Change one side.')}</h2><p>${L('Geser pengatur panjang x. Lebarnya akan menyesuaikan agar kelilingnya tetap 24 meter.','Move the slider to change length x. The width adjusts so the perimeter stays at 24 metres.')}</p>${slider('garden-x',L('Panjang taman, x','Garden length, x'),.5,11.5,.1,3,'m')}<div class="metrics" id="garden-metrics"></div>${prompt(L('Jika taman dibuat semakin panjang, apakah luasnya selalu bertambah?','If the garden gets longer, does its area always increase?'))}<button class="quiet" id="snapshot">＋ ${L('Simpan ukuran ini','Save this experiment')}</button><div class="snapshots" id="snapshots"></div></div></div><div class="twocol">${card(L('Dari keliling ke lebar','From perimeter to width'),L('<p>Misalkan panjangnya x dan lebarnya y. Jumlah panjang keempat sisi adalah 24 meter.</p>','<p>Let x be the length and y be the width. All four sides add up to 24 metres.</p>')+formula('2x + 2y = 24<br>x + y = 12<br>y = 12 − x')+`<p class="small">${L('Kedua sisi harus positif, jadi 0 < x < 12.','Both sides must be positive, so 0 < x < 12.')}</p>`,'blue',L('HUBUNGKAN DENGAN YANG SUDAH DIKENAL','CONNECT TO WHAT YOU KNOW'))}${card(L('Dari ukuran ke luas','From dimensions to area'),L('<p>Luas = panjang × lebar. Setelah lebar diganti dengan 12 − x, kita hanya perlu memilih x.</p>','<p>Area = length × width. Replacing the width with 12 − x leaves just one input to choose.</p>')+formula('A(x) = x(12 − x)',L('x adalah ukuran yang dipilih; A(x) adalah luas yang dihasilkan.','x is the side you choose; A(x) is the area it produces.')),'sand',L('BUAT MODELNYA','BUILD THE MODEL'))}</div>${practice(numeric('garden-best',L('Menurut percobaanmu, berapa luas terbesar yang mungkin?','From your experiment, what is the largest possible area?'),36,L('Bandingkan taman 5 × 7, 6 × 6, dan 7 × 5 meter.','Compare gardens of 5 × 7, 6 × 6, and 7 × 5 metres.'),L('Ya, 36 m² saat kedua sisinya 6 m. Nanti kita buktikan bahwa tidak ada ukuran lain yang lebih baik.','Yes: 36 m² when both sides are 6 m. Later, we will prove that no other dimensions do better.'),'m²')+choice('garden-model',L('Mengapa lebarnya ditulis 12 − x?','Why is the width 12 − x?'),L(['Karena panjang + lebar = 12.','Karena luasnya selalu 12.','Karena semua taman harus berbentuk persegi.'],['Because length + width = 12.','Because the area is always 12.','Because every garden must be a square.']),0,L('Tepat. Dari 2x + 2y = 24, kita mendapat x + y = 12. Jadi y = 12 − x.','Exactly. Dividing 2x + 2y = 24 by 2 gives x + y = 12, so y = 12 − x.'),L('Mulai dari keliling: 2x + 2y = 24. Bagi kedua ruas dengan 2.','Start with the perimeter: 2x + 2y = 24. Divide both sides by 2.')))}<div class="note"><b>${L('Simpan pertanyaan ini:','Keep this question:')}</b> ${L('Percobaan memberi dugaan. Bagaimana membuktikannya untuk semua ukuran, termasuk ukuran desimal?','An experiment gives us a guess. How can we prove it for every size, including decimals?')}</div>`+bottom();}
function change(){return heading(L('02 · MEMAHAMI PERUBAHAN','02 · THE ART OF CHANGE'),L('Tujuan sama. Gerak berbeda.','Same finish. Different journeys.'),L('A dan B sama-sama menempuh 16 meter dalam 4 detik. Apakah itu berarti mereka selalu bergerak dengan kecepatan yang sama?','A and B both travel 16 metres in 4 seconds. Does that mean they always move at the same speed?'))+`<div class="lab"><div class="stage"><div class="stage-label">${L('JARAK DARI TITIK AWAL','DISTANCE FROM THE START')}</div><div id="race-art"></div><div class="choices"><button class="quiet" id="race-play">▶ ${L('Putar gerakan','Play journey')}</button><button class="quiet" id="race-reset">↺ ${L('Ulang dari awal','Start again')}</button></div></div><div class="panel"><div class="card-kicker">${L('AMATI GERAKNYA','WATCH THE MOTION')}</div><h2>${L('Siapa yang berubah cepat?','How does each one move?')}</h2><div class="legend"><span class="teal-dot">A: d = 4t</span><span class="mauve-dot">B: d = t²</span></div><p>${L('t adalah waktu dalam detik; d adalah jarak dalam meter. Kita amati dari t = 0 sampai t = 4.','t is time in seconds; d is distance in metres. We observe from t = 0 to t = 4.')}</p>${slider('race-t',L('Waktu, t','Time, t'),0,4,.05,1,'s')}<div class="metrics" id="race-metrics"></div>${prompt(L('Bandingkan tambahan jarak B pada setiap detik. Tetap sama atau semakin besar?','Compare the extra distance B travels each second. Is it constant or getting larger?'))}</div></div><div class="twocol">${card(L('Temukan polanya','Read the pattern'),`<div class="table-wrap"><table><thead><tr><th>t (s)</th><th>A (m)</th><th>B (m)</th><th>${L('Tambahan B tiap detik','Extra distance for B')}</th></tr></thead><tbody>${[0,1,2,3,4].map(t=>`<tr><td>${t}</td><td>${4*t}</td><td>${t*t}</td><td>${t?2*t-1:'—'}</td></tr>`).join('')}</tbody></table></div><p>${L('A selalu bertambah 4 meter. Tambahan jarak B adalah 1, 3, 5, lalu 7 meter.','A adds 4 metres every second. B adds 1, then 3, then 5, then 7 metres.')}</p>`)}${card(L('Seberapa cepat berubah?','How quickly does it change?'),L('<p>Untuk membandingkan perubahan, bagi perubahan nilai y dengan perubahan nilai x. Hasilnya adalah gradien rata-rata antara dua titik.</p>','<p>Divide the change in y by the change in x. This gives the average gradient between two points.</p>')+formula('m = (y₂ − y₁) / (x₂ − x₁)',L('Untuk gerak: kecepatan rata-rata = perubahan jarak ÷ selang waktu.','For motion: average speed = change in distance ÷ time elapsed.')),'sand')}</div><div class="stage wide-stage"><div class="stage-label">${L('GRAFIK JARAK TERHADAP WAKTU','DISTANCE–TIME GRAPHS')}</div><div id="race-plot"></div><div class="legend"><span class="teal-dot">A: d = 4t</span><span class="mauve-dot">B: d = t²</span></div></div>${practice(numeric('linear-gradient',L('Berapa gradien garis y = 3x + 2?','What is the gradient of y = 3x + 2?'),3,L('Jika x naik 1, berapa tambahan y?','If x increases by 1, how much does y increase?'),L('Benar, 3. Setiap x naik 1, y naik 3. Angka +2 hanya menggeser posisi garis.','Correct: 3. Every increase of 1 in x adds 3 to y. The +2 shifts the line.'))+numeric('avg-gradient',L('Pada y = x², berapa gradien rata-rata dari x = 2 ke x = 4?','For y = x², find the average gradient from x = 2 to x = 4.'),6,L('Gunakan titik (2,4) dan (4,16). Hitung (16 − 4) ÷ (4 − 2).','Use (2,4) and (4,16). Calculate (16 − 4) ÷ (4 − 2).'),L('Ya: (16 − 4)/(4 − 2) = 6. Tambahan y adalah 12, tetapi gradiennya adalah 12 ÷ 2 = 6.','Yes: (16 − 4)/(4 − 2) = 6. The change in y is 12; the gradient is 12 ÷ 2 = 6.')))}${choice('same-speed',L('Jarak akhirnya sama. Apakah kecepatannya selalu sama?','They finish at the same distance. Is their speed always the same?'),L(['Ya, karena tujuan akhirnya sama.','Tidak. Kecepatan mereka dapat berbeda di sepanjang perjalanan.'],['Yes, because they finish together.','No. Their speeds can differ along the journey.']),1,L('Tepat. A menambah 4 m tiap detik, sedangkan B bergerak semakin cepat.','Exactly. A adds 4 m each second, while B speeds up.'),L('Bandingkan tambahan jarak B pada detik pertama dan terakhir.','Compare B’s extra distance in the first and last seconds.'))}<div class="note"><b>${L('Pertanyaan berikutnya:','Next question:')}</b> ${L('Dua titik memberi gradien rata-rata. Bagaimana mencari kemiringan tepat di satu titik pada kurva?','Two points give an average gradient. How can we find the slope at just one point on a curve?')}</div>`+bottom();}
function zoom(){return heading(L('03 · MENDEKAT SEDIKIT DEMI SEDIKIT','03 · THE INFINITE ZOOM'),L('Semakin dekat, semakin jelas.','Closer. Closer. A pattern appears.'),L('Pada kurva y = x², kita ingin mengetahui kemiringan tepat di A = (2,4). Kita mulai dengan gradien antara A dan titik lain, B, lalu mendekatkan B ke A.','On y = x², we want the slope exactly at A = (2,4). Start with the gradient between A and another point, B, then bring B closer to A.'))+`<div class="lab"><div class="stage"><div class="stage-label">${L('DUA TITIK YANG SEMAKIN DEKAT','BRING TWO POINTS CLOSER')}</div><div id="zoom-art"></div><div class="legend"><span class="teal-dot">${L('Kurva','Curve')}</span><span class="mauve-dot">${L('Garis AB','Secant AB')}</span><span class="gold-dot">${L('Garis singgung di A','Tangent at A')}</span></div><div class="choices"><button class="quiet" data-zoom-side="right">${L('Dari kanan','From the right')} →</button><button class="quiet" data-zoom-side="left">← ${L('Dari kiri','From the left')}</button><button class="quiet" id="zoom-reset">${L('Atur ulang skala','Reset scale')}</button></div><div class="coordinate-controls">${slider('zoom-scale',L('Zoom koordinat di sekitar A','Coordinate zoom around A'),0,4,.01,0).replace('<span>0 </span><span>4 </span>', '<span>1×</span><span>10,000×</span>')}<div id="zoom-window" class="coordinate-window"></div><p class="small">${L('Zoom mempersempit rentang sumbu x dan y. Geser pengatur posisi B untuk mengubah h.','Zoom narrows the x- and y-axis ranges. Use the B slider to change h.')}</p></div><div class="art-caption" id="zoom-caption"></div></div><div class="panel"><div class="card-kicker">${L('COBA KEDUA ARAH','TRY BOTH DIRECTIONS')}</div><h2>${L('Perkecil jaraknya.','Make the gap smaller.')}</h2><p>${L('h adalah selisih koordinat x antara B dan A. Geser ke kanan agar |h| makin kecil. Titik B tetap berbeda dari A.','h is the difference in x-coordinates between B and A. Move right to shrink |h|. B stays different from A.')}</p>${slider('zoom-level',L('Seberapa dekat B ke A?','How close is B to A?'),0,4,.01,0)}<div class="metrics" id="zoom-metrics"></div>${prompt(L('Gradien AB mendekati angka berapa, baik dari kiri maupun dari kanan?','Which number does the gradient of AB approach from both sides?'))}</div></div><div class="twocol">${card(L('Hitung gradien AB','Calculate the gradient of AB'),'<div class="formula" id="zoom-formula"></div>','blue',L('RUMUS YANG SUDAH DIKENAL','A FAMILIAR FORMULA'))}${card(L('Mendekati, bukan membagi dengan nol','Approach zero; do not divide by it'),L('<p>Nilai yang didekati disebut <b>limit</b>. Kita membiarkan h semakin dekat ke 0, tetapi tidak mengganti h dengan 0 dalam pecahan semula.</p>','<p>The value being approached is called a <b>limit</b>. We let h get closer to 0 without putting h = 0 in the original fraction.</p>')+formula('lim<sub>h→0</sub> (4+h) = 4',L('Artinya: saat h mendekati 0, nilai 4+h mendekati 4.','As h approaches 0, the value of 4+h approaches 4.')),'sand')}</div>${practice(numeric('limit-slope',L('Berapa kemiringan kurva di A yang ditunjukkan percobaan ini?','What slope at A does the experiment suggest?'),4,L('Amati gradien 3.999 dan 4.001. Keduanya mendekati angka yang sama.','Compare gradients 3.999 and 4.001. They approach the same number.'),L('Ya, 4. Itulah gradien garis singgung y = x² di x = 2.','Yes: 4. This is the tangent slope of y = x² at x = 2.'))+numeric('limit-pattern',L('Pola 2.1, 2.01, 2.001, … mendekati angka berapa?','What number does 2.1, 2.01, 2.001, … approach?'),2,L('Selisih tiap angka dari 2 semakin kecil.','Each number gets closer to 2.'),L('Benar, 2. Nilainya dapat mendekati 2 tanpa harus sama dengan 2 pada suatu langkah.','Correct: 2. The terms approach 2 without needing to equal 2 at any step.')))}${choice('zero-h',L('Mengapa tidak langsung memasukkan h = 0 ke pecahan gradien semula?','Why not substitute h = 0 into the original gradient fraction?'),L(['Karena perhitungannya harus panjang.','Karena penyebutnya menjadi 0.','Karena x tidak boleh sama dengan 2.'],['Because the calculation must be long.','Because the denominator would be 0.','Because x cannot equal 2.']),1,L('Tepat. 0/0 tidak terdefinisi. Kita menyederhanakan untuk h ≠ 0, lalu mencari nilai yang didekati.','Exactly. 0/0 is undefined. We simplify for h ≠ 0, then find the limiting value.'),L('Lihat penyebut pada rumus perubahan y dibagi h.','Look at the denominator in the change in y divided by h.'))}<div class="note">${L('Pada kurva mulus seperti x², garis AB mendekati garis singgung. Di sudut tajam, satu kemiringan seperti ini belum tentu ada.','On a smooth curve such as x², AB approaches the tangent. At a sharp corner, a single slope need not exist.')}</div>`+bottom();}
function derivativeDefinition(){
  return `<section class="concept-card derivative-definition">
    <h3>${L('Definisi umum turunan','The general definition of a derivative')}</h3>
    <p>${L('Untuk fungsi f yang terdefinisi di sekitar x, ambil dua titik pada grafiknya: (x, f(x)) dan (x+h, f(x+h)). Saat h ≠ 0, pecahan di bawah ini adalah gradien garis yang menghubungkan kedua titik.', 'For a function f defined around x, take two points on its graph: (x, f(x)) and (x+h, f(x+h)). For h ≠ 0, the fraction below is the slope of the line through them.')}</p>
    <div class="formula"><math display="block" aria-label="${L('Turunan f di x adalah limit saat h mendekati nol dari f di x tambah h dikurangi f di x, dibagi h','The derivative of f at x is the limit as h approaches zero of f of x plus h minus f of x, divided by h')}"><mi>f</mi><mo>′</mo><mo>(</mo><mi>x</mi><mo>)</mo><mo>=</mo><munder><mi>lim</mi><mrow><mi>h</mi><mo>→</mo><mn>0</mn></mrow></munder><mfrac><mrow><mi>f</mi><mo>(</mo><mi>x</mi><mo>+</mo><mi>h</mi><mo>)</mo><mo>−</mo><mi>f</mi><mo>(</mo><mi>x</mi><mo>)</mo></mrow><mi>h</mi></mfrac></math></div>
    <p>${L('Jika limit dari kiri dan kanan ada dan sama dengan satu bilangan hingga, bilangan itu adalah f′(x). Kita membiarkan h mendekati nol dari kedua arah sambil tetap memakai h ≠ 0 dalam pecahan.', 'If the left and right limits exist and agree at a finite value, that value is f′(x). We let h approach zero from both sides while keeping h ≠ 0 in the fraction.')}</p>
    <p>${L('Contoh: untuk f(x) = x², pecahannya menjadi 2x+h. Saat h mendekati 0, nilainya mendekati 2x. Jadi f′(x) = 2x.', 'Example: for f(x) = x², the fraction simplifies to 2x+h. As h approaches 0, this approaches 2x, so f′(x) = 2x.')}</p>
  </section>`;
}
function derivative(){return heading(L('04 · TURUNAN PERTAMAMU','04 · YOUR FIRST DERIVATIVE'),L('Dari aljabar ke turunan.','You already have the ingredients.'),L('Turunan memberi kemiringan kurva pada titik yang kita pilih. Kita temukan turunan x² dengan langkah aljabar sederhana, lalu lihat artinya pada gambar.','A derivative gives the slope of a curve at a chosen point. Use simple algebra to discover the derivative of x², then see what it means on the graph.'))+`<div class="lab"><div class="stage"><div class="stage-label">${L('KURVA y = x² · GARIS SINGGUNG BERWARNA EMAS','CURVE y = x² · TANGENT IN GOLD')}</div><div id="derivative-art"></div></div><div class="panel"><div class="card-kicker">${L('HUBUNGKAN ANGKA DAN GAMBAR','CONNECT THE NUMBERS AND THE GRAPH')}</div><h2>${L('Pilih satu titik.','Choose a point.')}</h2><p>${L('Geser posisi x. Amati bagaimana kemiringan garis singgung berubah.','Move x along the curve. Watch the tangent slope change.')}</p>${slider('derive-x',L('Posisi x pada kurva','Position x on the curve'),-2,2,.1,1)}<div class="metrics" id="derivative-metrics"></div>${prompt(L('Apa perbedaan kemiringan di sebelah kiri dan kanan x = 0?','How does the slope differ to the left and right of x = 0?'))}</div></div><div class="twocol">${card(L('Dua titik, seperti sebelumnya','Start with two points'),L('<p>A = (x,x²) dan B = (x+h,(x+h)²). Gunakan rumus gradien untuk h ≠ 0.</p>','<p>A = (x,x²) and B = (x+h,(x+h)²). Use the gradient formula with h ≠ 0.</p>')+formula('m = ((x+h)² − x²) / h'))}${card(L('Satu nama baru: turunan','A new name: derivative'),L('<p>Turunan f ditulis <b>f′(x)</b>, dibaca “f aksen x”. Nilainya menunjukkan kemiringan kurva f pada posisi x.</p><p>Contoh: jika f′(2) = 4, kemiringan kurva di x = 2 adalah 4.</p>','<p>The derivative of f is written <b>f′(x)</b>, read “f prime of x”. Its value gives the slope of f at position x.</p><p>For example, f′(2) = 4 means the slope at x = 2 is 4.</p>'),'sand')}</div>${derivativeDefinition()}<section class="discovery-card"><div class="card-kicker">${L('TEMUKAN RUMUSNYA · BUKA SATU LANGKAH DULU','DISCOVER THE FORMULA · ONE STEP AT A TIME')}</div><h2>${L('Mengapa turunannya 2x?','Why is the derivative 2x?')}</h2><div id="derive-steps" class="derive-steps"></div><button class="primary" id="derive-next">${L('Buka langkah berikutnya','Reveal the next step')} →</button></section>${numeric('expand-check',L('Cek aljabar: (x+h)² = x² + __ xh + h². Angka berapa yang hilang?','Algebra check: (x+h)² = x² + __ xh + h². What is missing?'),2,L('Kalikan (x+h)(x+h). Ada dua suku xh.','Expand (x+h)(x+h). There are two xh terms.'),L('Tepat. xh + hx = 2xh. Langkah inilah yang membantu kita menemukan turunan.','Exactly. xh + hx = 2xh. This is the key expansion in the discovery.'))}<details class="toolbox"><summary>${L('Bekal tambahan: aturan pangkat sederhana','A small toolbox: simple power rules')}</summary><p>${L('Buka bagian ini setelah turunan x² terasa jelas. Untuk pangkat bulat positif n, turunan xⁿ adalah nxⁿ⁻¹.','Explore this after x² feels clear. For positive integers n, the derivative of xⁿ is nxⁿ⁻¹.')}</p><div class="table-wrap"><table><thead><tr><th>f(x)</th><th>f′(x)</th><th>${L('Maknanya','Meaning')}</th></tr></thead><tbody><tr><td>5</td><td>0</td><td>${L('Garis mendatar','A horizontal line')}</td></tr><tr><td>x</td><td>1</td><td>${L('Gradien tetap 1','Constant slope of 1')}</td></tr><tr><td>x²</td><td>2x</td><td>${L('Gradien bergantung pada x','The slope depends on x')}</td></tr><tr><td>x³</td><td>3x²</td><td>${L('Pangkat menjadi pengali','The exponent becomes a factor')}</td></tr><tr><td>x⁴</td><td>4x³</td><td>${L('Pangkat turun satu','The exponent decreases by one')}</td></tr></tbody></table></div>${formula('(axⁿ)′ = a · n · xⁿ⁻¹',L('Turunan konstanta adalah 0. Untuk penjumlahan atau pengurangan, turunkan tiap suku.','The derivative of a constant is 0. Differentiate sums and differences term by term.'))}<p>${L('Contoh: (3x² + 5x − 7)′ = 6x + 5.','Example: (3x² + 5x − 7)′ = 6x + 5.')}</p></details>${practice(freeAnswer('deriv-a',L('1. Tentukan turunan f(x) = x².','1. Differentiate f(x) = x².'),['2x'],L('Ingat hasil penemuan kita: f′(x) = 2x.','Recall our discovery: f′(x) = 2x.'),L('Ya, f′(x) = 2x. Misalnya di x = 3, kemiringannya adalah 6.','Yes: f′(x) = 2x. For example, the slope at x = 3 is 6.'))+freeAnswer('deriv-b',L('2. Tentukan turunan f(x) = 3x² + 5.','2. Differentiate f(x) = 3x² + 5.'),['6x'],L('Kalikan turunan x² dengan 3. Turunan konstanta 5 adalah 0.','Multiply the derivative of x² by 3. The constant 5 has derivative 0.'),L('Tepat: f′(x) = 6x.','Correct: f′(x) = 6x.'))+freeAnswer('deriv-c',L('3. Tentukan turunan A(x) = 12x − x².','3. Differentiate A(x) = 12x − x².'),['12-2x'],L('Turunan 12x adalah 12. Kurangi dengan turunan x².','The derivative of 12x is 12. Subtract the derivative of x².'),L('Benar: A′(x) = 12 − 2x. Kita akan memakai hasil ini untuk taman.','Correct: A′(x) = 12 − 2x. We will use this for the garden.'))+freeAnswer('deriv-d',L('4. Coba aturan pangkat: tentukan turunan x³.','4. Try the power rule: differentiate x³.'),['3x^2'],L('Pangkat 3 menjadi pengali, lalu pangkatnya berkurang menjadi 2.','Bring down the exponent 3, then reduce the exponent to 2.'),L('Ya, turunannya 3x².','Yes: the derivative is 3x².'))+freeAnswer('deriv-e',L('5. Tentukan turunan F(x) = x² − x⁴.','5. Differentiate F(x) = x² − x⁴.'),['2x-4x^3'],L('Turunkan masing-masing suku: x² menjadi 2x, dan x⁴ menjadi 4x³.','Differentiate each term: x² becomes 2x, and x⁴ becomes 4x³.'),L('Tepat: F′(x) = 2x − 4x³. Bentuk ini akan muncul pada soal lingkaran.','Exactly: F′(x) = 2x − 4x³. This will appear in the circle challenge.')))}<div class="note">${L('Tidak perlu buru-buru menghafal. Yang utama: kamu tahu bahwa turunan menyatakan kemiringan kurva pada titik yang dipilih.','There is no rush to memorize rules. The main idea is that a derivative gives the slope at a chosen point.')}</div>`+bottom();}
function optimize(){return heading(L('05 · MENCARI NILAI TERBAIK','05 · FINDING THE SWEET SPOT'),L('Kapan bertambah menjadi berkurang?','When growing turns into shrinking.'),L('Kita kembali ke taman dengan pagar 24 meter. Sekarang amati luasnya sekaligus tanda turunannya: kapan luas bertambah, kapan berhenti bertambah, dan kapan berkurang?','Return to the garden with 24 metres of fencing. Watch both its area and its derivative: when does the area increase, stop increasing, and decrease?'))+`<div class="lab"><div class="stage"><div class="stage-label">${L('LUAS TAMAN · A(x) = 12x − x²','GARDEN AREA · A(x) = 12x − x²')}</div><div id="opt-art"></div><div class="art-caption" id="opt-caption"></div></div><div class="panel"><div class="card-kicker">${L('BACA ARAH PERUBAHANNYA','READ THE DIRECTION OF CHANGE')}</div><h2>${L('Perhatikan kemiringannya.','Read the slope.')}</h2>${slider('opt-x',L('Panjang taman, x','Garden length, x'),.2,11.8,.1,3,'m')}<div class="metrics" id="opt-metrics"></div>${formula('A′(x) = 12 − 2x')}<p id="opt-status" class="live-insight" role="status"></p></div></div><div class="sign-cards">${card(L('Sebelum x = 6','Before x = 6'),formula('A′(x) > 0')+`<p>↗ ${L('Gradien positif: luas bertambah saat x bertambah.','Positive slope: area increases as x increases.')}</p>`,'blue')}${card(L('Saat x = 6','At x = 6'),formula('A′(x) = 0')+`<p>→ ${L('Garis singgung mendatar di puncak.','The tangent is horizontal at the peak.')}</p>`,'sand')}${card(L('Sesudah x = 6','After x = 6'),formula('A′(x) < 0')+`<p>↘ ${L('Gradien negatif: luas berkurang saat x bertambah.','Negative slope: area decreases as x increases.')}</p>`,'mauve')}</div>${numeric('opt-root',L('Selesaikan 12 − 2x = 0. Berapa x?','Solve 12 − 2x = 0. What is x?'),6,L('Dari 12 = 2x, bagi kedua ruas dengan 2.','From 12 = 2x, divide both sides by 2.'),L('Ya, x = 6. Lebarnya juga 6, jadi luasnya 36 m². Turunan berubah dari positif ke negatif, sehingga luas ini maksimum.','Yes: x = 6. The width is also 6, giving 36 m². The derivative changes from positive to negative, confirming a maximum.'),'m')}${scaffold('garden-proof',L(['Cari ukuran terbaik di antara semua 0 < x < 12.','Temukan saat A′(x) = 0, lalu periksa tanda di kiri dan kanannya.','A′(5) = 2 dan A′(7) = −2. Luas bertambah sebelum x = 6 dan berkurang setelahnya.'],['Find the best size among all 0 < x < 12.','Find where A′(x) = 0, then check the sign on each side.','A′(5) = 2 and A′(7) = −2. The area increases before x = 6 and decreases afterwards.']),paired(formula('A(x) = 36 − (x−6)² ≤ 36')+`<p>${L('Kuadrat tidak negatif. Luas terbesar adalah 36 m² dan tercapai saat x = 6.','A square is nonnegative. The largest area is 36 m², reached at x = 6.')}</p>`,formula('A′(x) = 12 − 2x<br>A′(6) = 0')+`<p>${L('Untuk 0 < x < 6, turunannya positif. Untuk 6 < x < 12, negatif. Jadi luas naik lalu turun, dengan maksimum 36 m² di x = 6.','The derivative is positive for 0 < x < 6 and negative for 6 < x < 12. The area rises then falls, reaching a maximum of 36 m² at x = 6.')}</p>`))}${section(L('Pola pikir yang bisa dipakai lagi','A strategy you can reuse'))}<div class="pathcards">${[['01',L('Buat model.','Build a model.'),L('Pilih variabel, tentukan nilai yang boleh dipilih, lalu tulis fungsi yang ingin dimaksimumkan.','Choose a variable, state its allowed values, and write the function to maximize.')],['02',L('Cari kandidat.','Find candidates.'),L('Cari titik dengan turunan nol. Perhatikan juga batas nilai variabel.','Find points with zero derivative. Also consider the domain boundaries.')],['03',L('Periksa alasannya.','Check and explain.'),L('Lihat tanda turunannya dan nilai di batas. Apakah hasilnya masuk akal?','Check derivative signs and boundary values. Does the result make sense?')]].map(([n,t,p])=>`<div class="pathcard"><div class="number">${n}</div><h3>${t}</h3><p>${p}</p></div>`).join('')}</div>${choice('zero-not-max',L('Jika f′(a) = 0, apakah a pasti memberi nilai maksimum?','If f′(a) = 0, is a always a maximum?'),L(['Ya, selalu.','Belum tentu. Titik itu masih perlu diperiksa.'],['Yes, always.','Not necessarily. We must still check the point.']),1,L('Tepat. Pada x², gradien nol di titik minimum. Pada x³, gradien nol bisa terjadi saat grafik tetap naik.','Exactly. For x², zero slope occurs at a minimum. For x³, it can occur while the curve keeps increasing.'),L('Ingat titik terbawah pada y = x². Garis singgungnya juga mendatar.','Think of the bottom of y = x². Its tangent is also horizontal.'))}<details class="toolbox"><summary>${L('Lihat dua contoh: gradien nol belum cukup','See two examples: zero slope is not enough')}</summary><div class="twocol">${card('y = x²',`<p>${L('Minimum di x = 0.','A minimum at x = 0.')}</p>`+plot({fn:x=>x*x,xmin:-2,xmax:2,ymin:-1,ymax:4,xtick:1,ytick:1,point:{x:0,y:0,label:L('minimum','minimum')},slope:0}))}${card('y = x³',`<p>${L('Grafik tetap naik melewati x = 0.','The graph keeps rising through x = 0.')}</p>`+plot({fn:x=>x*x*x,xmin:-2,xmax:2,ymin:-8,ymax:8,xtick:1,ytick:4,point:{x:0,y:0,label:L('gradien nol','zero slope')},slope:0}),'mauve')}</div></details><div class="note mauve"><b>${L('Jangan lupa batasnya.','Remember the boundaries.')}</b> ${L('Untuk f(x) = x pada 0 ≤ x ≤ 1, maksimum terjadi di x = 1, meskipun turunannya selalu 1.','For f(x) = x on 0 ≤ x ≤ 1, the maximum is at x = 1, even though the derivative is always 1.')}</div>`+bottom();}
function olympiad(){let lab=memory.lab||'pair';return heading(L('06 · LABORATORIUM OLIMPIADE','06 · THE OLYMPIAD LAB'),L('Satu soal, dua sudut pandang.','New tools. Familiar reasoning.'),L('Mulai dari soal pemanasan. Lalu hubungkan geometri, aljabar, dan kalkulus untuk menyelesaikan tantangan dari soal kompetisi.','Begin with a warm-up, then connect geometry, algebra, and calculus to explore competition problems.'))+`<div class="subnav" role="group" aria-label="${L('Pilih tantangan','Choose a challenge')}">${[['pair',L('01 · Dua bilangan','01 · The perfect pair')],['circle',L('02 · Di dalam lingkaran','02 · Inside a circle')],['triangle',L('03 · Di dalam segitiga','03 · The hidden rectangle')]].map(([id,n])=>`<button class="quiet ${lab===id?'active':''}" data-lab="${id}" aria-pressed="${lab===id}">${n}</button>`).join('')}</div>${lab==='pair'?pairLab():lab==='circle'?circleLab():triangleLab()}${bottom()}`;}
function pairLab(){return `<div class="challenge-intro"><span class="badge">${L('PEMANASAN · SOAL BUATAN UNTUK PELAJARAN INI','WARM-UP · AUTHORED FOR THIS LESSON')}</span><h2>${L('Pasangan dengan hasil kali terbesar','The perfect pair')}</h2><p>${L('Dua bilangan real positif berjumlah 12. Berapa hasil kali terbesar yang bisa diperoleh?','Two positive real numbers add up to 12. What is the greatest product they can have?')}</p></div><div class="lab"><div class="stage"><div class="stage-label">${L('JUMLAH KEDUA BILANGAN TETAP 12','THE TWO NUMBERS ALWAYS ADD UP TO 12')}</div><div id="pair-art"></div>${slider('pair-x',L('Bilangan pertama, x','First number, x'),.1,11.9,.1,3)}<div class="metrics" id="pair-metrics"></div></div><div class="panel"><h2>${L('Ceritanya berbeda, polanya sama.','A new story. The same structure.')}</h2><p>${L('Bandingkan pasangan 2 dan 10, 4 dan 8, lalu 6 dan 6. Apa hubungannya dengan percobaan taman?','Compare 2 and 10, 4 and 8, then 6 and 6. How is this connected to the garden?')}</p>${formula('P(x) = x(12 − x)',L('Bilangan kedua adalah 12 − x, dengan 0 < x < 12.','The second number is 12 − x, with 0 < x < 12.'))}${prompt(L('Apakah pasangan yang lebih seimbang memberi hasil kali yang lebih besar?','Do more balanced pairs give a larger product?'))}</div></div>${numeric('pair-max',L('Berapa hasil kali terbesarnya?','What is the greatest possible product?'),36,L('Gunakan pasangan seimbang atau model x(12 − x).','Try the balanced pair or the model x(12 − x).'),L('Ya, 36 saat kedua bilangannya 6. Modelnya sama seperti luas taman.','Yes: 36 when both numbers are 6. It has the same model as the garden.'))}${scaffold('pair',L(['Jika bilangan pertama x, bilangan kedua adalah 12 − x.','Tuliskan hasil kalinya: P(x) = 12x − x².','Lengkapi kuadrat, atau cari saat P′(x) = 12 − 2x = 0.'],['If the first number is x, the second is 12 − x.','Write the product: P(x) = 12x − x².','Complete the square, or solve P′(x) = 12 − 2x = 0.']),paired(formula('P(x) = 36 − (x−6)² ≤ 36')+`<p>${L('Kesamaan tercapai saat x = 6.','Equality holds when x = 6.')}</p>`,formula('P′(x) = 12 − 2x')+`<p>${L('Turunan berubah dari positif ke negatif di x = 6. Jadi hasil kali maksimumnya 36.','The derivative changes from positive to negative at x = 6. The maximum product is 36.')}</p>`))}${numeric('pair-transfer',L('Coba sendiri: jumlah dua bilangan positif adalah 20. Berapa hasil kali terbesarnya?','Your turn: two positive numbers sum to 20. What is their maximum product?'),100,L('Coba pasangan yang seimbang, atau gunakan x(20 − x).','Try a balanced pair, or use x(20 − x).'),L('Tepat: 10 × 10 = 100. Modelnya dapat ditulis 100 − (x−10)².','Correct: 10 × 10 = 100. The model is 100 − (x−10)².'))}<button class="primary" data-lab="circle">${L('Lanjut ke lingkaran','Try the circle challenge')} →</button>`;}
function circleLab(){return `<div class="challenge-intro"><span class="badge">${L('SOAL KOMPETISI · OSK SMP 2012 · BAGIAN B, NO. 8 · DITULIS ULANG','PAST PAPER · OSK SMP 2012 · PART B, Q8 · PARAPHRASED')}</span><h2>${L('Persegi panjang terbesar dalam lingkaran','The largest rectangle in a circle')}</h2><p>${L('Sebuah persegi panjang memiliki keempat titik sudut pada lingkaran berjari-jari ½ satuan. Berapa luas terbesarnya?','A rectangle has all four vertices on a circle of radius ½ unit. What is its largest possible area?')}</p><a class="source-link" href="https://pusatolimpiade.wordpress.com/wp-content/uploads/2014/06/osnmatematikasmpkabupatenkota2012.pdf#page=4" target="_blank" rel="noopener">${L('Lihat arsip soal yang diketik ulang','View the retyped past-paper archive')} ↗</a></div><div class="lab"><div class="stage"><div class="stage-label">${L('KEEMPAT SUDUT TETAP BERADA PADA LINGKARAN','ALL FOUR VERTICES STAY ON THE CIRCLE')}</div><div id="circle-art"></div></div><div class="panel"><h2>${L('Cari bentuk terbaiknya.','Find the best shape.')}</h2><p>${L('Geser sisi x. Sisi y akan menyesuaikan agar semua sudut tetap menyentuh lingkaran.','Move side x. Side y adjusts so that all four vertices stay on the circle.')}</p>${slider('circle-x',L('Sisi mendatar, x','Horizontal side, x'),.05,.99,.01,.4)}<div class="metrics" id="circle-metrics"></div>${prompt(L('Bentuk apa yang tampaknya menghasilkan luas terbesar?','Which shape seems to give the largest area?'))}</div></div><div class="twocol">${card(L('Geometri memberi hubungan','Geometry gives the constraint'),L('<p>Diagonal persegi panjang merupakan diameter lingkaran. Karena jari-jarinya ½, diameternya adalah 1.</p>','<p>The rectangle’s diagonal is a diameter of the circle. With radius ½, the diameter is 1.</p>')+formula('x² + y² = 1<br>A = xy',L('Gunakan Pythagoras. Kedua sisi positif: 0 < x < 1.','Use Pythagoras. Both sides are positive: 0 < x < 1.')))}${card(L('Sederhanakan sebelum menurunkan','Simplify before differentiating'),L('<p>Luas A tidak negatif. Jadi mencari A terbesar sama dengan mencari A² terbesar. Dengan cara ini, kita bisa menghindari turunan bentuk akar.</p>','<p>Area A is nonnegative. Maximizing A is therefore equivalent to maximizing A². This avoids differentiating a square root.</p>')+formula('A² = x²(1−x²) = x²−x⁴'),'sand')}</div>${practice(choice('circle-diag',L('Mengapa x² + y² = 1?','Why is x² + y² = 1?'),L(['Karena kelilingnya 1.','Karena diagonalnya 1 dan berlaku Pythagoras.','Karena x + y = 1.'],['Because the perimeter is 1.','Because the diagonal is 1, by Pythagoras.','Because x + y = 1.']),1,L('Benar. x² + y² adalah kuadrat diagonal, yaitu 1².','Correct. x² + y² is the diagonal squared, which is 1².'),L('Hubungkan dua sudut berlawanan untuk membentuk diagonal.','Join two opposite vertices to draw a diagonal.'))+numeric('circle-area',L('Berapa luas terbesarnya? Boleh jawab dalam pecahan.','What is the largest area? You may use a fraction.'),.5,L('Dari (x−y)² ≥ 0, kita mendapat 2xy ≤ x²+y² = 1.','From (x−y)² ≥ 0, we get 2xy ≤ x²+y² = 1.'),L('Tepat, ½ satuan². Tercapai saat x = y = 1/√2.','Correct: ½ square unit, attained when x = y = 1/√2.'),L('satuan²','square units')))}${scaffold('circle',L(['Coba buat kedua sisinya hampir sama. Ingat bahwa kuadrat tidak negatif.','Untuk kalkulus, maksimalkan F(x) = A² agar tidak perlu menurunkan akar.','F(x) = x² − x⁴, sehingga F′(x) = 2x − 4x³ = 2x(1−2x²).'],['Try making the two sides nearly equal. Recall that a square is nonnegative.','For calculus, maximize F(x) = A² to avoid differentiating a root.','F(x) = x² − x⁴, so F′(x) = 2x − 4x³ = 2x(1−2x²).']),paired(formula('0 ≤ (x−y)² = 1−2xy<br>xy ≤ ½')+`<p>${L('Kesamaan saat x = y. Jadi bentuk persegi memberi luas maksimum ½.','Equality holds when x = y. A square gives the maximum area of ½.')}</p>`,formula('F′(x) = 2x(1−2x²)<br>x² = ½')+`<p>${L('Pada 0 < x < 1, tanda turunan berubah dari positif ke negatif saat x² = ½. Nilai maksimum F adalah ¼, sehingga maksimum A adalah ½. Di kedua batas, luas mendekati 0.','On 0 < x < 1, the derivative changes from positive to negative at x² = ½. The maximum F is ¼, so the maximum A is ½. At either boundary, the area approaches 0.')}</p>`))}${choice('square-transform',L('Mengapa A boleh diganti dengan A² saat mencari maksimumnya?','Why may we maximize A² instead of A?'),L(['Karena A ≥ 0, dan menguadratkan mempertahankan urutan nilai nonnegatif.','Karena semua nilai menjadi lebih kecil saat dikuadratkan.','Karena semua fungsi memiliki maksimum yang sama.'],['Because A ≥ 0, and squaring preserves the order of nonnegative values.','Because squaring always makes values smaller.','Because all functions have the same maximum.']),0,L('Tepat. Untuk 0 ≤ a < b, berlaku a² < b². Syarat tidak negatif itu penting.','Exactly. If 0 ≤ a < b, then a² < b². The nonnegative condition matters.'),L('Bandingkan 0.3 dengan 0.5, kemudian bandingkan kuadratnya.','Compare 0.3 with 0.5, then compare their squares.'))}<button class="primary" data-lab="triangle">${L('Lanjut ke segitiga','Explore the triangle')} →</button>`;}
function triangleLab(){return `<div class="challenge-intro"><span class="badge">${L('ADAPTASI TERBIMBING · OSN SMP NASIONAL 2012 · HARI 2, NO. 4','GUIDED ADAPTATION · OSN SMP NATIONAL 2012 · DAY 2, Q4')}</span><h2>${L('Persegi panjang di dalam segitiga','The hidden rectangle')}</h2><p>${L('Segitiga memiliki sisi 5 cm, 8 cm, dan √41 cm. Letakkan sisi bawah persegi panjang pada alas 8 cm, dengan kedua sudut atas menyentuh sisi miring segitiga. Berapa luas terbesar untuk posisi seperti ini?','A triangle has sides 5 cm, 8 cm, and √41 cm. Place the bottom of a rectangle on the 8 cm base, with both upper corners touching the sloping sides. What is its largest area in this arrangement?')}</p><a class="source-link" href="https://wing87.wordpress.com/wp-content/uploads/2012/08/osn_smp_2012_day21.pdf#page=4" target="_blank" rel="noopener">${L('Lihat arsip pembahasan Tutur Widodo','View Tutur Widodo’s solution archive')} ↗</a></div><div class="lab"><div class="stage"><div class="stage-label">${L('SISI BAWAH TETAP PADA BC','KEEP THE BOTTOM EDGE ON BC')}</div><div id="triangle-art"></div></div><div class="panel"><h2>${L('Naikkan sisi atasnya.','Raise the top edge.')}</h2><p>${L('Perhatikan: tinggi bertambah, tetapi lebarnya menyusut. Kedua perubahan ini menentukan luasnya.','Notice: the height increases, but the width shrinks. Together, these changes determine the area.')}</p>${slider('tri-h',L('Tinggi persegi panjang, h','Rectangle height, h'),.1,3.9,.1,1,'cm')}<div class="metrics" id="triangle-metrics"></div>${prompt(L('Bisakah kamu memperkirakan tinggi yang memberi luas terbesar?','Can you estimate the height that gives the largest area?'))}</div></div>${section(L('Pecah menjadi tiga langkah kecil','Break it into three small steps'))}<div class="mission-grid">${card(L('Cari tinggi segitiga.','Find the triangle’s height.'),`<p>${L('Misalkan BD = d, maka DC = 8−d. Kedua segitiga siku-siku memiliki tinggi AD yang sama.','Let BD = d, so DC = 8−d. The two right triangles share height AD.')}</p>${formula('25−d² = 41−(8−d)²<br>d = 3<br>AD = √(25−9) = 4 cm')}`,'blue',L('LANGKAH A','MISSION A'))}${card(L('Hubungkan tinggi dan lebar.','Relate height and width.'),`<p>${L('Segitiga kecil di atas persegi panjang sebangun dengan segitiga besar. Perbandingan lebarnya sama dengan perbandingan tingginya.','The small triangle above the rectangle is similar to the whole triangle. Their widths have the same ratio as their heights.')}</p>${formula('w / 8 = (4−h) / 4<br>w = 8−2h')}`,'sand',L('LANGKAH B','MISSION B'))}${card(L('Buat fungsi luas.','Build the area function.'),`<p>${L('Kalikan tinggi dengan lebar. Nilai h harus di antara 0 dan 4 agar persegi panjang tidak menjadi datar.','Multiply height by width. Keep h between 0 and 4 so the rectangle is not flat.')}</p>${formula('A(h) = h(8−2h)<br>= 8h−2h²')}`,'mint',L('LANGKAH C','MISSION C'))}</div>${practice(numeric('tri-width',L('Jika tingginya 1 cm, berapa lebarnya?','If the height is 1 cm, what is the width?'),6,L('Masukkan h = 1 ke w = 8−2h.','Substitute h = 1 into w = 8−2h.'),L('Ya, w = 8−2 = 6 cm.','Yes: w = 8−2 = 6 cm.'),'cm')+numeric('tri-height',L('Berapa tinggi yang menghasilkan luas terbesar?','Which height gives the largest area?'),2,L('A′(h) = 8−4h. Kapan turunannya nol?','A′(h) = 8−4h. When is the derivative zero?'),L('Benar, h = 2 cm. Lebarnya 4 cm dan luasnya 8 cm².','Correct: h = 2 cm. The width is 4 cm and the area is 8 cm².'),'cm'))}${scaffold('tri',L(['Saat tinggi bertambah, lebar berkurang. Kita perlu mempertimbangkan keduanya.','Gunakan kesebangunan: w = 8−2h, sehingga A(h) = 8h−2h².','A′(h) = 8−4h = 0 memberi h = 2. Periksa tanda di kedua sisinya.'],['Increasing the height reduces the width. We need to consider both.','Similarity gives w = 8−2h, so A(h) = 8h−2h².','Solving A′(h) = 8−4h = 0 gives h = 2. Check the sign on both sides.']),paired(formula('A(h) = 8−2(h−2)² ≤ 8')+`<p>${L('Untuk posisi pada gambar, luas maksimum 8 cm² tercapai pada tinggi 2 cm dan lebar 4 cm.','For the arrangement shown, the maximum is 8 cm² at height 2 cm and width 4 cm.')}</p>`,formula('A′(h) = 8−4h')+`<p>${L('Turunan positif sebelum h = 2, lalu negatif setelahnya. Jadi luas naik lalu turun, dan maksimumnya 8 cm².','The derivative is positive before h = 2 and negative afterwards. The area rises then falls, reaching 8 cm².')}</p>`))}<div class="note mauve"><b>${L('Apa yang sudah kita buktikan?','What have we proved?')}</b> ${L('Hasil ini berlaku untuk posisi dengan sisi bawah pada BC. Soal asli mengizinkan orientasi lain; pembuktian untuk semua orientasi memerlukan argumen geometri tambahan.','This proves the maximum when the bottom edge lies on BC. The original problem allows other orientations; covering them requires an additional geometric argument.')}</div>${reflection('triangle',L('Jelaskan dengan bahasamu: mengapa lebarnya menyusut ketika tinggi bertambah?','In your own words: why does the width shrink as the height increases?'),L('Karena segitiga kecil dan segitiga besar…','Because the small and large triangles…'))}`;}
function box(){return heading(L('07 · TANTANGAN KOTAK TANPA TUTUP','07 · THE OPEN-BOX CHALLENGE'),L('Potongan kecil, hasil berbeda.','A little cut. A surprising result.'),L('Karton persegi berukuran 12 × 12 cm akan dibuat menjadi kotak tanpa tutup. Potong persegi kecil yang sama besar di keempat sudutnya, lalu lipat sisi-sisinya. Berapa ukuran potongan agar volume kotaknya terbesar?','Turn a 12 × 12 cm square sheet into an open box. Cut identical small squares from all four corners, then fold up the sides. Which cut size gives the greatest volume?'))+`<span class="badge">${L('PENGAYAAN · SOAL BUATAN UNTUK PELAJARAN INI','ENRICHMENT · AUTHORED FOR THIS LESSON')}</span><div class="lab"><div class="stage"><div class="stage-label" id="box-label"></div><div id="box-art"></div><div class="choices"><button class="quiet" id="box-view"></button></div></div><div class="panel"><h2>${L('Makin tinggi, alas makin kecil.','More height, less base.')}</h2><p>${L('x adalah panjang sisi potongan di setiap sudut. Coba ukuran berbeda, lalu bandingkan volume kotaknya.','x is the side length of each corner cut. Try different sizes and compare the resulting volumes.')}</p>${slider('box-x',L('Ukuran potongan, x','Corner cut, x'),.1,5.9,.1,1,'cm')}<div class="metrics" id="box-metrics"></div>${prompt(L('Mengapa potongan yang lebih besar tidak selalu menghasilkan volume lebih besar?','Why does a larger cut not always give a larger volume?'))}</div></div><div class="twocol">${card(L('Perhatikan satu sisi karton.','Look at one edge of the sheet.'),L('<p>Dari panjang 12 cm, x terpotong di ujung kiri dan x lagi di ujung kanan. Sisa untuk alas adalah 12−2x.</p>','<p>Each 12 cm edge loses x at one end and x at the other. The base side is therefore 12−2x.</p>')+formula('V(x) = x(12−2x)²',L('Volume = tinggi × luas alas.','Volume = height × base area.')))}${card(L('Ukuran mana yang boleh dipilih?','Which cuts are allowed?'),L('<p>Ukuran potongan harus positif dan kurang dari setengah sisi karton.</p>','<p>The cut must be positive and smaller than half the sheet’s side.</p>')+formula('0 < x < 6')+`<p>${L('Saat x mendekati 0, kotak menjadi sangat pendek. Saat x mendekati 6, alasnya hampir hilang. Pada keduanya, volume mendekati 0.','As x approaches 0, the box becomes very shallow. As x approaches 6, its base nearly disappears. In both cases, volume approaches 0.')}</p>`,'sand')}</div><div class="stage wide-stage"><div class="stage-label">${L('GRAFIK VOLUME · TITIK MENGIKUTI UKURAN PILIHANMU','VOLUME GRAPH · THE DOT FOLLOWS YOUR CHOSEN CUT')}</div><div id="box-plot"></div></div>${practice(choice('box-base',L('Mengapa sisi alasnya 12−2x?','Why is each base side 12−2x?'),L(['Karena x dipotong dari kedua ujungnya.','Karena kotak memiliki dua sisi.','Karena tingginya 2x.'],['Because x is cut from both ends.','Because the box has two sides.','Because its height is 2x.']),0,L('Ya. Satu sisi kehilangan x di kiri dan x di kanan.','Yes. An edge loses x at the left and x at the right.'),L('Lihat dua sudut pada satu sisi karton yang sama.','Look at both corners along the same edge of the sheet.'))+numeric('box-opt',L('Berapa ukuran potongan yang memberi volume terbesar?','Which cut gives the greatest volume?'),2,L('V′(x) = 12(x−2)(x−6). Cari akar yang ada di dalam 0 < x < 6.','V′(x) = 12(x−2)(x−6). Find the root inside 0 < x < 6.'),L('Tepat, x = 2 cm. Alas 8 × 8 cm dan tinggi 2 cm menghasilkan volume 128 cm³.','Correct: x = 2 cm. A base of 8 × 8 cm and height 2 cm give a volume of 128 cm³.'),'cm'))}${scaffold('box',L(['Bandingkan potongan 1, 2, dan 3 cm. Apa dugaanmu?','Kembangkan dahulu: V(x) = 144x−48x²+4x³.','Turunannya V′(x) = 144−96x+12x² = 12(x−2)(x−6). Periksa tanda pada (0,2) dan (2,6).'],['Compare cuts of 1, 2, and 3 cm. What is your guess?','Expand first: V(x) = 144x−48x²+4x³.','Differentiate: V′(x) = 144−96x+12x² = 12(x−2)(x−6). Check the signs on (0,2) and (2,6).']),paired(formula('128−V(x) = 4(x−2)²(8−x)')+`<p>${L('Pada 0 < x < 6, ruas kanan tidak negatif. Jadi V(x) ≤ 128, dan kesamaan tercapai saat x = 2. Kalkulus membantu menemukan kandidat; bentuk ini membuktikan hasilnya.','For 0 < x < 6, the right side is nonnegative. Thus V(x) ≤ 128, with equality at x = 2. Calculus finds the candidate; this identity proves the result.')}</p>`,formula('V′(x) = 12(x−2)(x−6)')+`<p>${L('Turunan positif pada (0,2), lalu negatif pada (2,6). Volume di kedua batas mendekati 0. Jadi maksimum globalnya 128 cm³, tercapai saat x = 2.','The derivative is positive on (0,2), then negative on (2,6). The volume approaches 0 at both boundaries. The global maximum is 128 cm³ at x = 2.')}</p>`))}${numeric('box-transfer',L('Sekarang kartonnya 18 × 18 cm. Berapa potongan yang memberi volume terbesar?','Now the sheet is 18 × 18 cm. Which cut gives the greatest volume?'),3,L('Semua panjang menjadi 1.5 kali ukuran sebelumnya. Atau gunakan V(x) = x(18−2x)².','All lengths scale by 1.5. Or use V(x) = x(18−2x)².'),L('Benar, 3 cm. Untuk karton persegi dengan sisi s, potongan optimalnya s/6.','Correct: 3 cm. For a square sheet of side s, the optimal cut is s/6.'),'cm')}${reflection('box',L('Jelaskan: mengapa kotak yang lebih tinggi belum tentu memiliki volume lebih besar?','Explain: why is a taller box not always larger in volume?'),L('Ketika tingginya bertambah, alasnya…','When the height increases, the base…'))}<div class="note"><b>${L('Lihat perkembanganmu.','Look how far you have come.')}</b> ${L('Dari mencoba ukuran, kamu sudah bisa membuat fungsi dan menjelaskan mengapa satu ukuran adalah yang terbaik.','From testing sizes, you have learned to build a function and explain why one choice is the best.')}</div>`+bottom();}
function integral(){return heading(L('08 · PENEMUAN TAMBAHAN · OPSIONAL','08 · ONE MORE DISCOVERY · OPTIONAL'),L('Bagaimana jika potongannya dijumlahkan?','What if we add tiny pieces?'),L('Turunan membahas seberapa cepat sesuatu berubah. Sekarang kita coba ide lain: menjumlahkan bagian-bagian kecil untuk mengetahui total. Inilah awal intuisi integral.','A derivative tells us how quickly something changes. Now try another idea: add small contributions to find a total. This is a first glimpse of integration.'))+`<div class="lab"><div class="stage"><div class="stage-label">${L('KECEPATAN v(t) = 2t · DARI 0 SAMPAI 4 DETIK','SPEED v(t) = 2t · FROM 0 TO 4 SECONDS')}</div><div id="integral-art"></div><div class="legend"><span class="teal-dot">${L('Kecepatan sebenarnya','Actual speed')}</span><span class="bar-dot">${L('Perkiraan per selang waktu','Approximation per interval')}</span></div></div><div class="panel"><h2>${L('Dari kecepatan ke jarak.','From speed to distance.')}</h2><p>${L('Bagi waktu menjadi beberapa selang kecil. Pada tiap selang, pilih satu nilai kecepatan untuk memperkirakan jarak.','Split time into small intervals. Use one speed value on each interval to estimate the distance.')}</p>${slider('integral-n',L('Jumlah potongan waktu','Number of time intervals'),2,40,1,4)}<div class="choices"><button class="quiet" data-sum="left">${L('Pakai ujung kiri','Use left endpoints')}</button><button class="quiet" data-sum="right">${L('Pakai ujung kanan','Use right endpoints')}</button></div><div class="metrics" id="integral-metrics"></div><p class="live-insight" id="integral-caption"></p></div></div><div class="twocol">${card(L('Satu persegi panjang, satu perkiraan jarak.','One rectangle estimates a small distance.'),L('<p>Tinggi persegi panjang adalah kecepatan; lebarnya adalah selang waktu Δt. Luasnya memberi perkiraan jarak pada selang itu.</p>','<p>Its height is speed; its width is the time interval Δt. Its area estimates the distance travelled in that interval.</p>')+formula(L('jarak ≈ Σ kecepatan × Δt','distance ≈ Σ speed × Δt'),'m/s × s = m')+`<p>${L('Karena kecepatannya naik, ujung kiri memberi perkiraan terlalu kecil, sedangkan ujung kanan terlalu besar.','Because speed increases, left endpoints underestimate the distance and right endpoints overestimate it.')}</p>`)}${card(L('Total tepatnya bisa dicari dengan geometri.','Geometry gives the exact total.'),L('<p>Daerah di bawah v(t) = 2t dari t = 0 sampai 4 adalah segitiga: alas 4 detik dan tinggi 8 m/s.</p>','<p>The area under v(t) = 2t from t = 0 to 4 is a triangle: base 4 seconds, height 8 m/s.</p>')+formula(L('jarak = ½ × 4 × 8 = 16 m','distance = ½ × 4 × 8 = 16 m'))+`<p>${L('Saat potongannya semakin kecil, kedua perkiraan semakin dekat ke 16 meter.','As the intervals get smaller, both estimates approach 16 metres.')}</p>`,'sand')}</div>${numeric('integral-exact',L('Jika v(t) = 2t dari t = 0 sampai 3 detik, berapa jarak yang ditempuh?','For v(t) = 2t from t = 0 to 3 seconds, what distance is travelled?'),9,L('Gunakan luas segitiga dengan alas 3 dan tinggi 6.','Use the area of a triangle with base 3 and height 6.'),L('Ya, ½ × 3 × 6 = 9 meter. Geometri membantumu menghitung total jarak.','Yes: ½ × 3 × 6 = 9 metres. Geometry helps you find the total distance.'),'m')}<div class="note"><b>${L('Dua pertanyaan yang saling berhubungan.','Two connected questions.')}</b><br>${L('Turunan: “Seberapa cepat berubah di sini?”<br>Integral: “Berapa total yang terkumpul?”','Derivative: “How quickly is it changing here?”<br>Integral: “How much has accumulated?”')}</div>${reflection('last',L('Setelah mencoba semua ini, untuk apa kalkulus terasa berguna menurutmu?','After exploring these ideas, what feels useful about calculus?'),L('Sekarang aku bisa…','Now I can…'))}`+bottom();}
function teacherContent(){return `<div class="dialoghead"><h2>${L('Catatan pengajar','For the teacher')}</h2><button class="quiet" data-close="teacherDialog" aria-label="${L('Tutup catatan pengajar','Close teaching notes')}">✕</button></div><p>${L('Alur dirancang untuk tiga sesi sekitar 60 menit. Sesuaikan dengan pemahaman Meilani; semua bab tetap dapat dibuka.','Designed for three flexible sessions of about 60 minutes. Follow Meilani’s readiness; all chapters remain available.')}</p><ol><li><b>${L('Sesi 1:','Session 1:')}</b> ${L('Taman → perubahan → mendekat → turunan x². Berhenti di penemuan x² jika aljabarnya perlu waktu.','Garden → change → zoom → derivative of x². Stop at x² if the algebra needs more time.')}</li><li><b>${L('Sesi 2:','Session 2:')}</b> ${L('Latihan turunan → maksimum → dua bilangan → lingkaran.','Derivative practice → maxima → pair → circle.')}</li><li><b>${L('Sesi 3:','Session 3:')}</b> ${L('Adaptasi segitiga → kotak → soal penerapan baru. Integral bersifat opsional.','Triangle adaptation → box → transfer question. Integration is optional.')}</li></ol><h3>${L('Bekal yang perlu dicek','Readiness to check')}</h3><p>${L('Substitusi, gradien, pengembangan (x+h)², faktorisasi, dan kesebangunan. Utamakan makna turunan x² sebelum aturan pangkat umum. Petunjuk bersifat pilihan; tidak ada penalti untuk jawaban salah.','Substitution, gradients, expanding (x+h)², factorisation, and similarity. Prioritize the meaning of the derivative of x² before the general power rule. Hints are optional; incorrect answers have no penalty.')}</p><h3>${L('Keterangan sumber','Source notes')}</h3><p>${L('Soal dua bilangan dan kotak dibuat untuk pelajaran ini. Keduanya tidak diberi label soal kompetisi asli.','The pair and open-box problems are authored for this lesson, not presented as past-paper questions.')}</p><p><a href="https://pusatolimpiade.wordpress.com/wp-content/uploads/2014/06/osnmatematikasmpkabupatenkota2012.pdf" target="_blank" rel="noopener">OSK SMP 2012 · B8 ↗</a><br>${L('Arsip soal yang diketik ulang oleh Muhammad Yusuf. Soal lingkaran ditulis ulang dengan makna yang sama; bukan tautan naskah pada situs resmi penyelenggara.','A retyped archive credited to Muhammad Yusuf. The circle problem is paraphrased; this is not an original hosted on the organizer’s official site.')}</p><p><a href="https://wing87.wordpress.com/wp-content/uploads/2012/08/osn_smp_2012_day21.pdf" target="_blank" rel="noopener">OSN SMP 2012 · ${L('Hari 2, No. 4','Day 2, Q4')} ↗</a><br>${L('Arsip pembahasan oleh Tutur Widodo. Adaptasi di sini membatasi sisi bawah persegi panjang pada alas 8 cm. Hasil perhitungan itu tidak diklaim membuktikan semua orientasi.','Solution archive by Tutur Widodo. This lesson restricts the rectangle’s bottom edge to the 8 cm base. That calculation is not presented as a proof for all orientations.')}</p><h3>${L('Catatan dan progres','Notes and progress')}</h3><p>${L('Catatan, jawaban, ukuran percobaan, dan progres tersimpan di peramban ini. Data tidak berpindah otomatis ke perangkat lain.','Notes, answers, experiment snapshots, and progress stay in this browser. They do not sync across devices.')}</p><button class="quiet" id="exportBtn">${L('Unduh catatan belajar','Download learning notes')}</button><details><summary>${L('Hapus data belajar pada perangkat ini','Clear this device’s learning data')}</summary><p>${L('Catatan, jawaban, dan progres pada peramban ini akan dihapus.','This removes notes, answers, and progress in this browser.')}</p><button class="quiet danger" id="resetBtn">${L('Hapus progres lokal','Clear local progress')}</button></details>`;}
